<head>
    <title>BST Viewer</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #f0f0f0; }
        canvas { display: block; background-color: white; border: 1px solid #ccc; }
    </style>
</head>
<body>
    <canvas id="bstCanvas"></canvas>

    <script>
        const canvas = document.getElementById('bstCanvas');
        const ctx = canvas.getContext('2d');

        // Set canvas size
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        // Node properties
        const NODE_RADIUS = 20;
        const NODE_COLOR = '#3498db';
        const TEXT_COLOR = '#ffffff';
        const FONT = '14px Arial';

        // Tree structure (example for now)
        const tree = {
            value: 50,
            left: {
                value: 30,
                left: { value: 20 },
                right: { value: 40 }
            },
            right: {
                value: 70,
                left: { value: 60 },
                right: { value: 80 }
            }
        };

        // Function to draw a node
        function drawNode(x, y, value) {
            ctx.beginPath();
            ctx.arc(x, y, NODE_RADIUS, 0, Math.PI * 2);
            ctx.fillStyle = NODE_COLOR;
            ctx.fill();
            ctx.strokeStyle = '#2980b9';
            ctx.stroke();

            ctx.fillStyle = TEXT_COLOR;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.font = FONT;
            ctx.fillText(value, x, y);
        }

        // Function to draw a line between nodes
        function drawLine(x1, y1, x2, y2) {
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.strokeStyle = '#7f8c8d';
            ctx.lineWidth = 2;
            ctx.stroke();
        }

        // Function to draw the entire tree
        function drawTree(node, x, y, hOffset) {
            if (!node) return;

            drawNode(x, y, node.value);

            if (node.left) {
                const newX = x - hOffset;
                const newY = y + 70; // Vertical spacing
                drawLine(x, y + NODE_RADIUS, newX, newY - NODE_RADIUS);
                drawTree(node.left, newX, newY, hOffset / 2);
            }

            if (node.right){
                const newX = x + hOffset;
                const newY = y + 70;
                drawLine(x, y + NODE_RADIUS, newX, newY - NODE_RADIUS);
                drawTree(node.right, newX, newY, hOffset / 2);
            }
        }

        // Initial draw
        drawTree(tree, canvas.width / 2, 50, canvas.width / 4);

    </script>
</body>
</html>
